    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "a manual search was performed to identify any potentially missed studies by examining the reference lists of included studies and previously published reviews",
      "reason": "The types of reference lists examined are specified: reference lists of included studies and previously published reviews."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No backward or forward citation searching was reported."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No journals or conference proceedings were consulted directly as sources."
    }
  ],
  "confidence": 90
}

