{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No effect measure (e.g., risk ratio, mean difference) is specified for any outcome. The review reports a qualitative synthesis only, and neither the Methods nor Results sections state any effect measures used for the outcomes listed (e.g., gingival index, DMFT, knowledge)."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "10 articles that met the inclusion/exclusion criteria were included in the qualitative synthesis (Fig 1).",
      "reason": "The review conducted a qualitative synthesis with no meta-analysis; no effect sizes were synthesized, so interpretation thresholds for effect sizes do not apply."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "10 articles that met the inclusion/exclusion criteria were included in the qualitative synthesis (Fig 1).",
      "reason": "No quantitative synthesis was performed, so there was no need to re-express synthesized results using another effect measure."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "10 articles that met the inclusion/exclusion criteria were included in the qualitative synthesis (Fig 1).",
      "reason": "Since no effect measures were used in a qualitative-only synthesis, no justification of effect measure choice was required."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
